<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { BadgePercent, CircleAlert, Plus, RefreshCw, Send, X } from 'lucide-vue-next'
import { createCoupon, getCoupons, getStores, resubmitCoupon } from '../services/merchant.js'
const rows = ref([]); const stores = ref([]); const loading = ref(false); const open = ref(false); const editing = ref(null); const message = ref('')
const now = new Date(); const nextMonth = new Date(now.getTime() + 30 * 86400000)
const local = d => new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16)
const blank = () => ({ storeId: '', couponName: '', coverImageKey: 'merchant/coupons/default-cover.jpg', description: '', category: '餐饮', originalPrice: 100, salePrice: 88, stock: 100, limitCount: 1, groupEnabled: true, groupPeople: 3, groupTimeoutHours: 24, publishTime: local(now), expireTime: local(nextMonth), useStartTime: local(now), useEndTime: local(nextMonth), reservationRequired: false, refundable: true, holidayAvailable: true, stackable: false, useInstructions: '到店出示券码核销，每人限购数量以页面为准。' })
const form = reactive(blank())
const statusText = s => ({ PENDING: '待审核', APPROVED: '已通过', REJECTED: '已拒绝' }[s] || s)
const statusClass = s => ({ PENDING: 'warning', APPROVED: 'success', REJECTED: 'danger' }[s] || '')
const rejected = computed(() => rows.value.filter(x => x.auditStatus === 'REJECTED').length)
function normalize(data) { return { ...data, storeId: String(data.storeId), publishTime: String(data.publishTime).slice(0, 16), expireTime: String(data.expireTime).slice(0, 16), useStartTime: String(data.useStartTime).slice(0, 16), useEndTime: String(data.useEndTime).slice(0, 16) } }
function showCreate() { editing.value = null; Object.assign(form, blank(), { storeId: stores.value[0]?.storeId || '' }); open.value = true }
function showResubmit(row) { editing.value = row; Object.assign(form, normalize(row)); open.value = true }
async function load() { loading.value = true; message.value = ''; try { [rows.value, stores.value] = await Promise.all([getCoupons(), getStores()]) } catch (e) { message.value = e.message } finally { loading.value = false } }
async function submit() { const payload = { ...form, storeId: String(form.storeId), originalPrice: Number(form.originalPrice), salePrice: Number(form.salePrice), stock: Number(form.stock), limitCount: Number(form.limitCount), groupPeople: form.groupEnabled ? Number(form.groupPeople) : null, groupTimeoutHours: form.groupEnabled ? Number(form.groupTimeoutHours) : null, publishTime: `${form.publishTime}:00`, expireTime: `${form.expireTime}:00`, useStartTime: `${form.useStartTime}:00`, useEndTime: `${form.useEndTime}:00` }; try { editing.value ? await resubmitCoupon(editing.value.couponId, payload) : await createCoupon(payload); open.value = false; await load() } catch (e) { message.value = e.message } }
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><small class="eyebrow">TRAVEL BENEFITS</small><h1>优惠券管理</h1><p>提交后进入平台审核；只有已通过且有效的优惠券会展示给 App 用户。</p></div><div class="actions"><button class="btn" @click="load"><RefreshCw :class="{ spin: loading }" />刷新</button><button class="btn primary" :disabled="!stores.length" @click="showCreate"><Plus />发布优惠券</button></div></div><div v-if="message" class="notice danger">{{ message }}</div><div v-if="rejected" class="notice"><CircleAlert />有 {{ rejected }} 个优惠被拒绝，可修改后重新提交审核。</div><div v-if="!stores.length && !loading" class="notice">请先在“门店管理”创建门店，才能发布优惠券。</div><section class="panel"><div class="panel-head"><div><h2>优惠券列表</h2><p>共 {{ rows.length }} 个经营项目</p></div><BadgePercent /></div><div v-if="!rows.length && !loading" class="empty compact"><BadgePercent /><h2>暂无优惠券</h2></div><div v-else class="table-wrap"><table><thead><tr><th>优惠信息</th><th>适用门店</th><th>价格</th><th>库存 / 已售</th><th>平台审核</th><th>上线状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.couponId"><td><b>{{ row.couponName }}</b><small>{{ row.category }} · ID {{ row.couponId }}</small></td><td>{{ row.storeName }}</td><td><b class="price">¥{{ row.salePrice }}</b><small>原价 ¥{{ row.originalPrice }}</small></td><td>{{ row.stock }} / {{ row.soldCount }}</td><td><span class="tag" :class="statusClass(row.auditStatus)">{{ statusText(row.auditStatus) }}</span><small v-if="row.rejectReason" class="reject">{{ row.rejectReason }}</small></td><td><span class="tag">{{ row.offerStatus }}</span></td><td><button v-if="row.auditStatus === 'REJECTED'" class="btn sm" @click="showResubmit(row)"><Send />修改并重提</button><span v-else class="muted">—</span></td></tr></tbody></table></div></section><div v-if="open" class="modal-mask" @click.self="open = false"><form class="modal wide" @submit.prevent="submit"><div class="modal-head"><div><h2>{{ editing ? '修改并重新提交' : '发布优惠券' }}</h2><p>优惠价不得高于原价，结束时间必须晚于开始时间。</p></div><button type="button" class="plain-icon" @click="open = false"><X /></button></div><div class="form-grid"><label><span>适用门店</span><select v-model="form.storeId" required><option disabled value="">请选择</option><option v-for="s in stores" :key="s.storeId" :value="s.storeId">{{ s.storeName }}</option></select></label><label><span>经营类目</span><select v-model="form.category"><option>餐饮</option><option>酒店</option><option>景区</option><option>汽车服务</option><option>户外装备</option></select></label><label class="full"><span>优惠券名称</span><input v-model="form.couponName" required maxlength="128"></label><label><span>原价</span><input v-model="form.originalPrice" type="number" min="0.01" step="0.01" required></label><label><span>优惠价</span><input v-model="form.salePrice" type="number" min="0.01" step="0.01" required></label><label><span>库存</span><input v-model="form.stock" type="number" min="1" required></label><label><span>每人限购</span><input v-model="form.limitCount" type="number" min="1" required></label><label><span>发布时间</span><input v-model="form.publishTime" type="datetime-local" required></label><label><span>下线时间</span><input v-model="form.expireTime" type="datetime-local" required></label><label><span>可用开始</span><input v-model="form.useStartTime" type="datetime-local" required></label><label><span>可用结束</span><input v-model="form.useEndTime" type="datetime-local" required></label><label class="full"><span>封面文件标识</span><input v-model="form.coverImageKey" required></label><label class="full"><span>优惠说明</span><textarea v-model="form.description" required maxlength="1000"></textarea></label><label class="full"><span>使用须知</span><textarea v-model="form.useInstructions" required maxlength="1000"></textarea></label><div class="checks full"><label><input v-model="form.reservationRequired" type="checkbox">需要预约</label><label><input v-model="form.refundable" type="checkbox">支持退款</label><label><input v-model="form.holidayAvailable" type="checkbox">节假日可用</label><label><input v-model="form.stackable" type="checkbox">可叠加使用</label></div></div><div class="modal-foot"><button type="button" class="btn" @click="open = false">取消</button><button class="btn primary">{{ editing ? '重新提交审核' : '提交平台审核' }}</button></div></form></div></div></template>
